mapper.sql:
from `Auct_Master` A
left join `Auct_Category` B on A.cnum = B.cnum

	inner join `Auct_Concern` C on A.anum = C.anum and C.unum = #{unum}



		A.unum = #{unum}


		and (A.prod_name like concat('%', #{value}, '%') or B.category like concat('%', #{value}, '%'))


		and A.cnum = #{cnum}



			and A.end_chk = 'N' and now() >= A.auct_start and now() <= A.auct_end


			and A.end_chk = 'N' and now() < A.auct_start


			and (A.end_chk <> 'N' or now() > A.auct_end)
